ALTER TABLE public.settings ADD COLUMN rand_rate numeric NOT NULL DEFAULT 0;
COMMENT ON COLUMN public.settings.rand_rate IS 'Rand units per USD; zero means not configured and Rand trading is blocked.';
ALTER TABLE public.rate_history ADD COLUMN rand_rate numeric NOT NULL DEFAULT 0;
ALTER TABLE public.sales ADD COLUMN rand_rate numeric NOT NULL DEFAULT 0;
ALTER TABLE public.sales ADD COLUMN zig_rate numeric;
UPDATE public.sales SET zig_rate=exchange_rate;
ALTER TABLE public.sale_payments ADD COLUMN exchange_rate numeric NOT NULL DEFAULT 1;
UPDATE public.sale_payments p SET exchange_rate=s.exchange_rate FROM public.sales s WHERE s.id=p.sale_id AND p.currency='ZiG';
ALTER TABLE public.sales DROP CONSTRAINT sales_currency_check;
ALTER TABLE public.sales ADD CONSTRAINT sales_currency_check CHECK(currency IN ('USD','ZiG','ZAR'));
ALTER TABLE public.sale_payments DROP CONSTRAINT sale_payments_currency_check;
ALTER TABLE public.sale_payments ADD CONSTRAINT sale_payments_currency_check CHECK(currency IN ('USD','ZiG','ZAR'));
ALTER TABLE public.cashier_shifts ADD COLUMN opening_float_zar numeric NOT NULL DEFAULT 0;
ALTER TABLE public.cashier_shifts ADD COLUMN actual_cash_zar numeric;
ALTER TABLE public.cashier_shifts ADD COLUMN expected_cash_zar numeric;
ALTER TABLE public.cashier_shifts ADD COLUMN variance_zar numeric;
CREATE OR REPLACE FUNCTION public.currency_rate(p_currency text,p_zig numeric,p_rand numeric) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE r numeric; BEGIN r:=CASE p_currency WHEN 'USD' THEN 1 WHEN 'ZiG' THEN p_zig WHEN 'ZAR' THEN p_rand ELSE NULL END; IF r IS NULL OR r<=0 OR r::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Set a positive exchange rate for % before trading',p_currency; END IF; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.currency_rate(text,numeric,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.currency_rate(text,numeric,numeric) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.log_rate_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.zig_rate IS DISTINCT FROM OLD.zig_rate OR NEW.rand_rate IS DISTINCT FROM OLD.rand_rate THEN INSERT INTO public.rate_history(zig_rate,rand_rate,store_id) VALUES(NEW.zig_rate,NEW.rand_rate,NEW.store_id); END IF; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.complete_sale(jsonb,jsonb,numeric,text,uuid)'::regprocedure) INTO d;
d:=replace(d,'v_rate numeric; v_shift uuid;','v_rate numeric; v_rand numeric; v_shift uuid;');
d:=replace(d,'select zig_rate into v_rate from settings where id=1;','select zig_rate, rand_rate into v_rate,v_rand from settings where store_id=public.current_store_id(); PERFORM public.currency_rate(p_currency,v_rate,v_rand);');
d:=replace(d,'where id=(it->>''product_id'')::uuid and active for update','where id=(it->>''product_id'')::uuid and store_id=public.current_store_id() and active for update');
d:=replace(d,'where id = p_customer and active','where id = p_customer and store_id=public.current_store_id() and active for update');
d:=replace(d,'v_amt := case when pay->>''currency''=''ZiG'' then (pay->>''amount'')::numeric / v_rate else (pay->>''amount'')::numeric end;','IF NOT EXISTS(SELECT 1 FROM public.payment_types WHERE code=pay->>''method'' AND active AND store_id=public.current_store_id()) OR (pay->>''amount'')::numeric < 0 THEN RAISE EXCEPTION ''Invalid payment''; END IF; v_amt := (pay->>''amount'')::numeric / public.currency_rate(pay->>''currency'',v_rate,v_rand);');
d:=replace(d,'currency, exchange_rate, amount_paid, change_given, shift_id, customer_id)','currency, exchange_rate, amount_paid, change_given, shift_id, customer_id,zig_rate,rand_rate)');
d:=replace(d,'p_currency, v_rate, round(v_paid,2), v_change, v_shift, p_customer)','p_currency, CASE WHEN p_currency=''ZAR'' THEN v_rand ELSE v_rate END, round(v_paid,2), v_change, v_shift, p_customer,v_rate,v_rand)');
d:=replace(d,'insert into sale_payments (sale_id, method, currency, amount)','insert into sale_payments (sale_id, method, currency, amount,exchange_rate)');
d:=replace(d,'(x->>''amount'')::numeric from jsonb_array_elements(p_payments) x;','(x->>''amount'')::numeric,public.currency_rate(x->>''currency'',v_rate,v_rand) from jsonb_array_elements(p_payments) x;');
d:=replace(d,'''rate'', v_rate, ''shift_id''','''rate'', CASE WHEN p_currency=''ZAR'' THEN v_rand ELSE v_rate END, ''shift_id''');
EXECUTE d;
SELECT pg_get_functiondef('public.complete_offline_sale(text,jsonb,jsonb,numeric,text,timestamp with time zone,uuid)'::regprocedure) INTO d;
d:=replace(d,'v_uid uuid := auth.uid(); v_rate numeric;','v_uid uuid := auth.uid(); v_rate numeric; v_rand numeric;');
d:=replace(d,'where client_ref = p_client_ref','where client_ref = p_client_ref and store_id=public.current_store_id() and cashier_id=auth.uid()');
d:=replace(d,'select zig_rate into v_rate from rate_history where effective_from <= v_when','select zig_rate,rand_rate into v_rate,v_rand from rate_history where store_id=public.current_store_id() and effective_from <= v_when');
d:=replace(d,'if v_rate is null then select zig_rate into v_rate from settings where id=1; end if;','if v_rate is null then select zig_rate,rand_rate into v_rate,v_rand from settings where store_id=public.current_store_id(); end if; PERFORM public.currency_rate(p_currency,v_rate,v_rand); IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_payments) x WHERE public.is_account_method(x->>''method'')) THEN RAISE EXCEPTION ''Account sales require online checkout''; END IF;');
d:=replace(d,'where id=(it->>''product_id'')::uuid for update','where id=(it->>''product_id'')::uuid and store_id=public.current_store_id() and active for update');
d:=replace(d,'case when x->>''currency''=''ZiG'' then (x->>''amount'')::numeric / v_rate else (x->>''amount'')::numeric end','(x->>''amount'')::numeric / public.currency_rate(x->>''currency'',v_rate,v_rand)');
d:=replace(d,'offline, synced_at)','offline, synced_at,zig_rate,rand_rate)');
d:=replace(d,'p_currency, v_rate, round(v_paid,2)','p_currency, CASE WHEN p_currency=''ZAR'' THEN v_rand ELSE v_rate END, round(v_paid,2)');
d:=replace(d,'p_client_ref, true, now())','p_client_ref, true, now(),v_rate,v_rand)');
d:=replace(d,'sale_payments (sale_id, method, currency, amount, verified)','sale_payments (sale_id, method, currency, amount, verified,exchange_rate)');
d:=replace(d,'public.is_cash_method(x->>''method'') from','public.is_cash_method(x->>''method''),public.currency_rate(x->>''currency'',v_rate,v_rand) from');
d:=replace(d,'''rate'', v_rate, ''underpaid''','''rate'', CASE WHEN p_currency=''ZAR'' THEN v_rand ELSE v_rate END, ''underpaid''');
EXECUTE d;
END $$;